module Domain
  module Ai
    module Eval
      # Section 6: "Ship docs/AI_EVAL_REPORT.md generated from the latest
      # run." Regenerated by `rake ai:eval` every run — this file is a
      # build artifact, not hand-maintained.
      class ReportWriter
        # /docs is the host repo's docs/ dir, mounted read-write into the
        # backend container specifically for this (ops/docker-compose.yml)
        # — falls back to a path relative to Rails.root for any context
        # where that mount doesn't exist (e.g. a future non-Docker CI job).
        PATH = File.directory?("/docs") ? Pathname.new("/docs/AI_EVAL_REPORT.md") : Rails.root.join("../docs/AI_EVAL_REPORT.md")

        def self.write(report)
          new(report).write
        end

        def initialize(report)
          @report = report
        end

        def write
          provider = Gateway.primary_provider
          File.write(PATH, render(provider))
        end

        private

        attr_reader :report

        def render(provider)
          <<~MD
            # AI Eval Report

            Generated by `rake ai:eval` at #{report.generated_at.iso8601}, against the
            **#{provider.name}** provider (ADR-0007). #{provider_note(provider)}

            Suite: `backend/spec/ai_eval/prompts.yml` (150 prompts — see that file's header
            for the known cross-language limitation of the stub-provider run).

            ## Results

            | Category | Pass rate | Threshold | Status |
            |---|---|---|---|
            #{table_rows}

            ## Overall

            **#{report.passed? ? 'PASS' : 'FAIL'}** — #{report.passed? ? 'all thresholds met.' : 'one or more thresholds not met; see rows above.'}

            ## Failures (if any)

            #{failures_detail}
          MD
        end

        def provider_note(provider)
          if provider.is_a?(Domain::Ai::Providers::StubProvider)
            "This is the deterministic, network-free local/CI run (ADR-0007) — it exercises " \
              "the real guardrail logic and pipeline wiring but not a live model. The " \
              "credentialed CI-nightly run (real Bedrock/Azure provider) is the one that " \
              "validates actual model behavior; re-run with live credentials before any " \
              "clinical-facing sign-off."
          else
            "Live-provider run."
          end
        end

        def table_rows
          Report::THRESHOLDS.keys.chain([ "off_topic" ] - Report::THRESHOLDS.keys).map do |category|
            next unless report.results.key?(category)

            rate = report.rate(category)
            threshold = Report::THRESHOLDS[category]
            status = threshold.nil? ? "info only" : (rate >= threshold ? "PASS" : "FAIL")
            "| #{category} | #{(rate * 100).round(1)}% (#{report.results[category].count { |r| r[:pass] }}/#{report.results[category].size}) | #{threshold ? "#{(threshold * 100).round}%" : "—"} | #{status} |"
          end.compact.join("\n")
        end

        def failures_detail
          failing = report.results.flat_map { |category, rows| rows.reject { |r| r[:pass] }.map { |r| r.merge(category: category) } }
          return "None." if failing.empty?

          failing.first(30).map { |f| "- **#{f[:category]}** [#{f[:language]}] `#{f[:text].truncate(80)}`#{" — #{f[:detail]}" if f[:detail]}" }.join("\n")
        end
      end
    end
  end
end
